/* pontos de encontro dos passeios de exemplo (no molde são texto simples) */
const SEMENTE_ENCONTRO = {
  'Praça principal, em frente à fonte': { en: 'Main square, in front of the fountain', fr: 'Place principale, devant la fontaine', it: 'Piazza principale, davanti alla fontana', de: 'Hauptplatz, vor dem Brunnen', es: 'Plaza principal, frente a la fuente' },
  'Estação central, saída principal': { en: 'Central station, main exit', fr: 'Gare centrale, sortie principale', it: 'Stazione centrale, uscita principale', de: 'Hauptbahnhof, Hauptausgang', es: 'Estación central, salida principal' },
  'No mirante, junto ao quiosque': { en: 'At the viewpoint, by the kiosk', fr: 'Au belvédère, près du kiosque', it: 'Al belvedere, vicino al chiosco', de: 'Am Aussichtspunkt, beim Kiosk', es: 'En el mirador, junto al quiosco' },
};

/* acrescenta as línguas novas em todo texto {pt, en} que tiver tradução */
function traduzSemente(o) {
  if (!o || typeof o !== 'object') return o;
  if (!Array.isArray(o) && 'pt' in o && 'en' in o) {
    const tr = SEMENTE_TR[JSON.stringify(o.pt)];
    if (tr) for (const l in tr) if (!(l in o)) o[l] = tr[l];
    return o;
  }
  if (typeof o.meeting === 'string' && SEMENTE_ENCONTRO[o.meeting]) o.meeting = { pt: o.meeting, ...SEMENTE_ENCONTRO[o.meeting] };
  for (const k in o) traduzSemente(o[k]);
  return o;
}

