Object.assign(IA_TR.fr, { ibConversas: 'Conversations', ibEnsinar: 'Former l’agent', ensLead: 'Dites à l’agent comment parler et quoi répondre. Visites, prix et places, il les lit déjà dans l’app.', ensReal: 'Tout s’enregistre tout seul. Dans la vraie app, cela s’applique aussitôt à votre WhatsApp et à votre Instagram ; ici, testez à côté.', ensSalvo: 'Enregistré ✓', ensP1: 'Ton', ensP2: 'Réponses prêtes', ensP3: 'Limites', ensP4: 'Testé', ensTomTit: '1. Ton', tom_simp: 'Chaleureux', tom_formal: 'Formel', tom_leve: 'Léger, avec emoji', tom_direto: 'Droit au but', ensTomPh: 'Autre chose ? Ex. : signer « l’équipe de Mari », tutoyer le client', ensFaqTit: '2. Réponses prêtes', ensFaqSub: 'Ce que les clients demandent toujours et que vous seul savez. Touchez une suggestion et écrivez à votre façon.', fqEncontro: 'Où est le point de rendez-vous ?', fqIdade: 'Y a-t-il un âge minimum ?', fqCancela: 'Puis-je annuler ou reporter ?', fqPaga: 'Comment je paie ?', fqLevar: 'Que dois-je apporter ?', fqChuva: 'Et s’il pleut ?', ensOutra: 'Autre question', ensPergunta: 'Question du client', ensResposta: 'Votre réponse', ensRespPh: 'Votre réponse, à votre façon. Ex. : devant la fontaine de la place, 10 min avant.', ensLimTit: '3. Limites', ensSempre: 'Toujours actif : n’invente jamais un prix, une date ou une place, et ne parle que de visites et de réservations.', ensPassaTit: 'Vous passe la conversation quand il s’agit de :', hReclama: 'Une réclamation', hDesconto: 'Une demande de remise', hGrupo: 'Un grand groupe', hEspecial: 'Une demande spéciale (allergie, accessibilité)', ensNuncaPh: 'Quelque chose à ne jamais dire ? Ex. : ne pas promettre les aurores boréales', ensTesteTit: 'Tester maintenant', ensTesteSub: 'Écrivez comme un client, dans n’importe quelle langue.', ensTestePh: 'Message du client…', ensLimpar: 'Recommencer', ensDemoAviso: 'Agent en direct indisponible : la réponse vient seulement de vos réponses prêtes.', ensNaoSei: 'Bonne question ! Le guide vous le confirme très vite. 🙂' });
Object.assign(IA_TR.it, { ibConversas: 'Conversazioni', ibEnsinar: 'Istruisci l’agente', ensLead: 'Di’ all’agente come parlare e cosa rispondere. Tour, prezzi e posti li legge già dall’app.', ensReal: 'Tutto si salva da solo. Nell’app vera vale subito per il tuo WhatsApp e il tuo Instagram; qui nella demo, provalo accanto.', ensSalvo: 'Salvato ✓', ensP1: 'Tono', ensP2: 'Risposte pronte', ensP3: 'Limiti', ensP4: 'Provato', ensTomTit: '1. Tono', tom_simp: 'Cordiale', tom_formal: 'Formale', tom_leve: 'Leggero, con emoji', tom_direto: 'Dritto al punto', ensTomPh: 'Altro? Es.: firma come «il team di Mari», dai del tu al cliente', ensFaqTit: '2. Risposte pronte', ensFaqSub: 'Quello che i clienti chiedono sempre e sai solo tu. Tocca un suggerimento e scrivi a modo tuo.', fqEncontro: 'Dov’è il punto d’incontro?', fqIdade: 'C’è un’età minima?', fqCancela: 'Posso annullare o spostare?', fqPaga: 'Come pago?', fqLevar: 'Cosa devo portare?', fqChuva: 'E se piove?', ensOutra: 'Altra domanda', ensPergunta: 'Domanda del cliente', ensResposta: 'La tua risposta', ensRespPh: 'La tua risposta, a modo tuo. Es.: davanti alla fontana della piazza, 10 min prima.', ensLimTit: '3. Limiti', ensSempre: 'Sempre attivo: non inventa mai prezzi, date o posti e parla solo di tour e prenotazioni.', ensPassaTit: 'Ti passa la conversazione quando si tratta di:', hReclama: 'Un reclamo', hDesconto: 'Una richiesta di sconto', hGrupo: 'Un gruppo numeroso', hEspecial: 'Una richiesta speciale (allergie, accessibilità)', ensNuncaPh: 'Qualcosa da non dire mai? Es.: non promettere l’aurora boreale', ensTesteTit: 'Provalo ora', ensTesteSub: 'Scrivi come un cliente, in qualsiasi lingua.', ensTestePh: 'Messaggio del cliente…', ensLimpar: 'Ricomincia', ensDemoAviso: 'Agente dal vivo non disponibile: la risposta viene solo dalle tue risposte pronte.', ensNaoSei: 'Bella domanda! Il guida te lo conferma a breve. 🙂' });
Object.assign(IA_TR.de, { ibConversas: 'Chats', ibEnsinar: 'Agenten anlernen', ensLead: 'Sag dem Agenten, wie er sprechen und was er antworten soll. Touren, Preise und Plätze liest er schon aus der App.', ensReal: 'Alles speichert sich von selbst. In der echten App gilt es sofort für dein WhatsApp und Instagram; hier in der Demo teste es daneben.', ensSalvo: 'Gespeichert ✓', ensP1: 'Tonfall', ensP2: 'Fertige Antworten', ensP3: 'Grenzen', ensP4: 'Getestet', ensTomTit: '1. Tonfall', tom_simp: 'Freundlich', tom_formal: 'Förmlich', tom_leve: 'Locker, mit Emoji', tom_direto: 'Auf den Punkt', ensTomPh: 'Noch etwas? Z. B. mit „Team Mari“ unterschreiben, Kunden duzen', ensFaqTit: '2. Fertige Antworten', ensFaqSub: 'Was Kunden immer fragen und nur du weißt. Tippe auf einen Vorschlag und schreib es auf deine Art.', fqEncontro: 'Wo ist der Treffpunkt?', fqIdade: 'Gibt es ein Mindestalter?', fqCancela: 'Kann ich stornieren oder umbuchen?', fqPaga: 'Wie bezahle ich?', fqLevar: 'Was soll ich mitbringen?', fqChuva: 'Und wenn es regnet?', ensOutra: 'Weitere Frage', ensPergunta: 'Kundenfrage', ensResposta: 'Deine Antwort', ensRespPh: 'Deine Antwort, auf deine Art. Z. B. vor dem Brunnen am Platz, 10 Min. vorher.', ensLimTit: '3. Grenzen', ensSempre: 'Immer aktiv: erfindet nie Preise, Termine oder Plätze und spricht nur über Touren und Buchungen.', ensPassaTit: 'Übergibt den Chat an dich bei:', hReclama: 'Beschwerden', hDesconto: 'Rabattanfragen', hGrupo: 'Großen Gruppen', hEspecial: 'Sonderwünschen (Allergie, Barrierefreiheit)', ensNuncaPh: 'Etwas, das er nie sagen darf? Z. B. keine Nordlichter versprechen', ensTesteTit: 'Jetzt testen', ensTesteSub: 'Schreib wie ein Kunde, in jeder Sprache.', ensTestePh: 'Nachricht des Kunden…', ensLimpar: 'Neu starten', ensDemoAviso: 'Live-Agent gerade nicht verfügbar: die Antwort kommt nur aus deinen fertigen Antworten.', ensNaoSei: 'Gute Frage! Der Guide bestätigt dir das gleich. 🙂' });
Object.assign(IA_TR.es, { ibConversas: 'Conversaciones', ibEnsinar: 'Enseñar al agente', ensLead: 'Dile al agente cómo hablar y qué responder. Tours, precios y plazas ya los lee solo de la app.', ensReal: 'Todo se guarda solo. En la app real vale al instante para tu WhatsApp y tu Instagram; aquí en la demo, pruébalo al lado.', ensSalvo: 'Guardado ✓', ensP1: 'Tono', ensP2: 'Respuestas listas', ensP3: 'Límites', ensP4: 'Probado', ensTomTit: '1. Tono', tom_simp: 'Cercano', tom_formal: 'Formal', tom_leve: 'Ligero, con emoji', tom_direto: 'Directo al grano', ensTomPh: '¿Algo más? Ej.: firma como «el equipo de Mari», tutea al cliente', ensFaqTit: '2. Respuestas listas', ensFaqSub: 'Lo que los clientes siempre preguntan y solo tú sabes. Toca una sugerencia y escríbelo a tu manera.', fqEncontro: '¿Dónde es el punto de encuentro?', fqIdade: '¿Hay edad mínima?', fqCancela: '¿Puedo cancelar o cambiar la fecha?', fqPaga: '¿Cómo pago?', fqLevar: '¿Qué debo llevar?', fqChuva: '¿Y si llueve?', ensOutra: 'Otra pregunta', ensPergunta: 'Pregunta del cliente', ensResposta: 'Tu respuesta', ensRespPh: 'Tu respuesta, a tu manera. Ej.: frente a la fuente de la plaza, 10 min antes.', ensLimTit: '3. Límites', ensSempre: 'Siempre activo: nunca inventa precios, fechas ni plazas, y solo habla de tours y reservas.', ensPassaTit: 'Te pasa la conversación cuando sea:', hReclama: 'Una queja', hDesconto: 'Un pedido de descuento', hGrupo: 'Un grupo grande', hEspecial: 'Un pedido especial (alergia, accesibilidad)', ensNuncaPh: '¿Algo que nunca deba decir? Ej.: no prometer auroras boreales', ensTesteTit: 'Probar ahora', ensTesteSub: 'Escribe como un cliente, en cualquier idioma.', ensTestePh: 'Mensaje del cliente…', ensLimpar: 'Empezar de nuevo', ensDemoAviso: 'Agente en vivo no disponible ahora: la respuesta sale solo de tus respuestas listas.', ensNaoSei: '¡Buena pregunta! El guía te lo confirma enseguida. 🙂' });
Object.assign(IA_TR.fr, { ensAplTit: 'Appliquer au vrai Instagram', ensAplTxt: 'Réservé au propriétaire : avec le code, le robot de @{c} répond avec cette formation dès le prochain message.', ensCodigo: 'Code du propriétaire', ensAplBt: 'Appliquer', ensAplOk: 'Appliqué — le prochain message partira ainsi', ensAplErro: 'Code incorrect.', ensAplSem: 'Le coffre n’a pas encore de code.', ensAplFalhou: 'Impossible de joindre le coffre. Réessayez.', ensTrazer: 'Charger la formation en ligne', ensTrouxe: 'Formation en ligne chargée ici.', ensNadaNoAr: 'Pas encore de formation en ligne : le robot utilise celle par défaut.' });
